def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    base_stock = 384.82991530041977  # OPT_PARAM: {"initial": 384.82991530041977, "min": 100.0, "max": 500.0, "type": "float"}
    lead_time_adjustment = 2.2216728605051372  # OPT_PARAM: {"initial": 2.2216728605051372, "min": 0.0, "max": 100.0, "type": "float"}
    demand_smoothing = 0.0  # OPT_PARAM: {"initial": 0.0, "min": 0.0, "max": 1.0, "type": "float"}

    effective_lead_time = quoted_lead_time - 3  # Normalize to [0,6] range
    adjusted_target = base_stock + lead_time_adjustment * effective_lead_time
    smoothed_demand = demand_smoothing * last_demand + (1 - demand_smoothing) * 100.0  # Exponential mean
    target = adjusted_target * (smoothed_demand / 100.0)

    order_amount = max(0.0, target - on_hand_inventory - sum(pipeline_orders))
    return order_amount
